#include <bits/stdc++.h>

using namespace std;

int main() {
    // your code goes here
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        int m = 3 * n;
        vector < long long > a(m);
        for (int i = 0; i < m; i++) {
            cin >> a[i];
        }
        sort(a.rbegin(), a.rend());

        vector < long long > pref(m + 1, 0);
        for (int i = 0; i < m; i++) {
            pref[i + 1] = pref[i] + a[i];
        }
        long long ans = 0;
        for (int i = 0; i <= n; i++) {
            int l = 0;
            int r = n - i;
            while (l < r) {
                int mid = l + (r - l) / 2;
                long long c = pref[i + 2 * mid] + 3 * pref[m - 2 * i - mid ];
                long long next = pref[i + 2 * mid + 2] + 3 * pref[m - 2 * i - mid - 1];
                if (next >= c) {
                    l = mid + 1;
                } else {
                    r = mid;
                }
            }
            int p = l;
            long long sum = 2 * pref[i] + pref[i + 2 * p] + 3 * pref[m - 2 * i - p];
            ans = max(ans, sum);
        }
        cout << ans << "\n";
    }
    return 0;
}
